"proposal": {
  "capability": "deployment.set-resources",
  "target": {"group": "apps", "kind": "Deployment", "namespace": "shop", "name": "search", "uid": "uid-deployment-search"},
  "params": {
    "containers": {
      "api": {
        "limits": {
          "cpu": "450m"
        }
      }
    }
  },
  "expected_effect": "The increased CPU limit should reduce throttling, allowing the container to meet its CPU demand and resolve readiness probe failures.",
  "rationale": "The container is consistently throttled at 55% of its CPU periods, with usage near its 300m limit. Increasing the limit to 450m provides more headroom, addressing the throttling without affecting memory or other resources.",
